from datetime import datetime, date, time
from time import sleep
# Target date and time
yo = date(2026, 2, 4)
cas = time(13, 30, 0)

# Combine into a full datetime
target_datetime = datetime.combine(yo, cas)


while True:
    now = datetime.now()
    novyTime = (target_datetime - now).total_seconds()
    print(novyTime)
    sleep(0.5)


